import { useState, useEffect, useRef, useCallback } from "react";
import "./Results.css";
import { saveAnalysis } from "./emailService";
import { saveMessage, getChatHistory } from "./chatService";
// ── Décode =?UTF-8?Q?...?= et =?UTF-8?B?...?= ─────────────────────────────
function decodeMimeHeader(str) {
  if (!str) return str;
  return str.replace(
    /=\?([^?]+)\?([BbQq])\?([^?]*)\?=/g,
    (_, charset, encoding, encoded) => {
      try {
        if (encoding.toUpperCase() === "B") {
          return decodeURIComponent(escape(atob(encoded)));
        } else {
          const qp = encoded
            .replace(/_/g, " ")
            .replace(/=([0-9A-Fa-f]{2})/g, (__, hex) =>
              String.fromCharCode(parseInt(hex, 16))
            );
          return decodeURIComponent(escape(qp));
        }
      } catch {
        return encoded;
      }
    }
  );
}

// ── Markdown → HTML parser ─────────────────────────────────────────────────
function parseMarkdown(text) {
  if (!text) return "";
  return text
    .replace(/\*\*(.+?)\*\*/g, "<strong>$1</strong>")
    .replace(/\*([^*\n]+?)\*/g, "<em>$1</em>")
    .replace(/^[\*\-]\s+(.+)$/gm, "<li>$1</li>")
    .replace(
      /(<li>[\s\S]*?<\/li>)(\n<li>[\s\S]*?<\/li>)*/g,
      (m) => `<ul>${m}</ul>`
    )
    .replace(/(?<!>)\n(?!<)/g, "<br/>")
    .replace(/(<br\/>){2,}/g, "<br/>");
}

// ── SVG : anneau de score ──────────────────────────────────────────────────
function ScoreRing({ score, color }) {
  const r = 45,
    circ = 2 * Math.PI * r;
  const offset = circ - (score / 100) * circ;
  return (
    <svg
      width="120"
      height="120"
      viewBox="0 0 120 120"
      style={{ transform: "rotate(-90deg)" }}
    >
      <circle
        cx="60"
        cy="60"
        r={r}
        fill="none"
        stroke="#f3f4f6"
        strokeWidth="9"
      />
      <circle
        cx="60"
        cy="60"
        r={r}
        fill="none"
        stroke={color}
        strokeWidth="9"
        strokeDasharray={circ}
        strokeDashoffset={offset}
        strokeLinecap="round"
        style={{ transition: "stroke-dashoffset 1.8s cubic-bezier(.4,0,.2,1)" }}
      />
    </svg>
  );
}

// ── SVG : icône bouton envoi ───────────────────────────────────────────────
function SendIcon() {
  return (
    <svg
      width="14"
      height="14"
      viewBox="0 0 24 24"
      fill="none"
      stroke="#fff"
      strokeWidth="2.2"
      strokeLinecap="round"
      strokeLinejoin="round"
    >
      <line x1="22" y1="2" x2="11" y2="13" />
      <polygon points="22 2 15 22 11 13 2 9 22 2" />
    </svg>
  );
}

// ── Icône robot / shield ───────────────────────────────────────────────────
function BotIcon() {
  return (
    <img
      src="/robot.png"
      alt="robot"
      className="robot-icon"
      style={{ width: 50, height: 50, objectFit: "contain" }}
    />
  );
}

// ── Composant principal ────────────────────────────────────────────────────
export default function Results({ emlData, onBack }) {
  const [report, setReport] = useState(null);
  const [emailId, setEmailId] = useState(null);
  const [msgs, setMsgs] = useState([]);
  const [input, setInput] = useState("");
  const [typing, setTyping] = useState(false);
  const [busy, setBusy] = useState(true);
  const [history, setHistory] = useState([]);
  const [pdfBusy, setPdfBusy] = useState(false);
  const msgsRef = useRef();

  // ── Métadonnées extraites du contenu brut EML ─────────────────────────
  const meta = emlData?.content
    ? {
        from: decodeMimeHeader(
          (emlData.content.match(/^From:\s*(.+)$/im) || [])[1] || "—"
        ),
        subject: decodeMimeHeader(
          (emlData.content.match(
            /^Subject:\s*([\s\S]+?)(?=\r?\n\S|\r?\n\r?\n)/im
          ) || [])[1]
            ?.replace(/\r?\n\s+/g, " ")
            .trim() || "—"
        ),
        date: (emlData.content.match(/^Date:\s*(.+)$/im) || [])[1] || "—",
        links: (emlData.content.match(/https?:\/\/[^\s"<>]+/g) || []).length,
        attach: (emlData.content.match(/filename[*=]+["']?([^"'\s;]+)/gi) || [])
          .length,
        file: emlData?.name || "—",
      }
    : {};

  // ── Auto-scroll ────────────────────────────────────────────────────────
  useEffect(() => {
    if (msgsRef.current)
      msgsRef.current.scrollTop = msgsRef.current.scrollHeight;
  }, [msgs, typing]);

  const addBot = (html, chips = []) =>
    setMsgs((p) => [...p, { role: "bot", text: html, chips }]);

  // ── Lancer l'analyse au montage ────────────────────────────────────────
  useEffect(() => {
    if (!emlData?.content) {
      addBot("Aucun email chargé. Retournez importer un fichier .eml.");
      setBusy(false);
      return;
    }
    runAnalysis();
  }, []); // eslint-disable-line

  // ── /api/analyze ───────────────────────────────────────────────────────
  const runAnalysis = async () => {
    setTyping(true);
    setBusy(true);
    try {
      const res = await fetch("/api/analyze", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          emlContent: emlData.content,
          emlName: emlData.name,
        }),
      });
      if (!res.ok) throw new Error(`Erreur ${res.status}`);
      const data = await res.json();

      // Format propre : data.report est l'objet direct
      let rep = null;
      if (
        data.report &&
        typeof data.report === "object" &&
        data.report.score !== undefined
      ) {
        rep = data.report;
      }

      // Fallback : JSON noyé dans data.result (ancienne version)
      if (!rep && data.result) {
        const text =
          typeof data.result === "string"
            ? data.result
            : JSON.stringify(data.result);
        const jm = text.match(/\{[\s\S]*?"score"[\s\S]*?"verdict"[\s\S]*?\}/);
        if (jm) {
          try {
            rep = JSON.parse(jm[0]);
          } catch (_) {}
        }
      }

      if (rep) setReport(rep);
      if (rep) {
        saveAnalysis(emlData.name, rep, meta).catch(() => {});
      }
      // Message HTML à afficher
      let msg =
        typeof data.result === "string"
          ? data.result
              .replace(/\{[\s\S]*?"score"[\s\S]*?"verdict"[\s\S]*?\}/, "")
              .trim()
          : "";

      // Chips : depuis la réponse serveur ou fallback défaut
      let chips =
        Array.isArray(data.chips) && data.chips.length
          ? data.chips
          : [
              "Risque de phishing ?",
              "Les liens sont-ils sûrs ?",
              "Que faire maintenant ?",
            ];

      // Support ancien format CHIPS: q1 | q2 | q3 dans le message
      const cm = msg.match(/CHIPS:\s*(.+)/);
      if (cm) {
        chips = cm[1]
          .split("|")
          .map((s) => s.trim())
          .slice(0, 3);
        msg = msg.replace(/CHIPS:.*/, "").trim();
      }

      setHistory([
        {
          role: "user",
          content: `[CTX] ${JSON.stringify(rep)} ${emlData.content.substring(
            0,
            2000
          )}`,
        },
        { role: "assistant", content: "Prêt." },
      ]);

      setTyping(false);
      setBusy(false);
      addBot(
        msg || "Analyse terminée. Posez-moi vos questions sur cet email.",
        chips
      );
    } catch (e) {
      setTyping(false);
      setBusy(false);
      addBot(`Une erreur est survenue : ${e.message}`);
    }
  };

  // ── /api/chat ──────────────────────────────────────────────────────────
  const sendMessage = useCallback(async () => {
    const text = input.trim();
    if (!text || typing) return;
    setInput("");
    setMsgs((p) => [
      ...p.map((m) => ({ ...m, chips: [] })),
      { role: "user", text },
    ]);

    const newH = [
      ...history.filter((m) => !m.content?.startsWith("[CTX]")),
      { role: "user", content: text },
    ];
    setHistory((p) => [...p, { role: "user", content: text }]);
    setTyping(true);

    try {
      const res = await fetch("/api/chat", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          messages: newH.slice(-10),
          report,
          emlSnippet: emlData?.content?.substring(0, 2000),
        }),
      });
      if (!res.ok) throw new Error(`Erreur ${res.status}`);
      const data = await res.json();
      setTyping(false);
      addBot(data.reply || "Désolé, veuillez réessayer.");
      setHistory((p) => [...p, { role: "assistant", content: data.reply }]);
    } catch (e) {
      setTyping(false);
      addBot(`Erreur : ${e.message}`);
    }
  }, [input, typing, report, history, emlData]);

  // ── /api/report/export → PDF backend ──────────────────────────────────
  const downloadPDF = async () => {
    if (!report) return alert("L'analyse n'est pas encore terminée.");
    setPdfBusy(true);
    try {
      const res = await fetch("/api/report/export", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ report, meta }),
      });
      if (!res.ok) throw new Error(`Erreur ${res.status}`);
      const blob = await res.blob();
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `CheckMail_${report.verdict}_${report.score}.pdf`;
      a.click();
      URL.revokeObjectURL(url);
    } catch (e) {
      alert(`Erreur PDF : ${e.message}`);
    } finally {
      setPdfBusy(false);
    }
  };

  // ── Score & verdict ────────────────────────────────────────────────────
  const score = report?.score ?? null;
  const ringColor =
    score === null
      ? "#e5e7eb"
      : score >= 70
      ? "#22c55e"
      : score >= 40
      ? "#f59e0b"
      : "#ef4444";

  const VM = {
    SAFE: { cls: "safe", label: "Email sûr" },
    SUSPICIOUS: { cls: "warn", label: "Suspect" },
    DANGEROUS: { cls: "danger", label: "Dangereux" },
  };
  const verdict = VM[report?.verdict] || {
    cls: "pending",
    label: "Analyse en cours",
  };

  // ── Rendu ──────────────────────────────────────────────────────────────
  return (
    <div className="rp-wrap">
      {/* ── Panneau gauche : rapport ─────────────────────────────────── */}
      <div className="rp-left">
        <div className="rp-header">
          <div>
            <h1>Rapport de sécurité</h1>
            <span className="rp-fname">{emlData?.name || "—"}</span>
          </div>
          <div className="rp-header-btns">
            {onBack && (
              <button className="rp-btn-outline" onClick={onBack}>
                ← Retour
              </button>
            )}
            <button
              className="rp-btn-primary"
              onClick={downloadPDF}
              disabled={pdfBusy || !report}
            >
              {pdfBusy ? "Génération…" : "Télécharger PDF"}
            </button>
          </div>
        </div>

        <div className="rp-divider" />

        {/* Score */}
        <div className="rp-score-section">
          <div className="rp-ring-wrap">
            <ScoreRing score={score ?? 0} color={ringColor} />
            <div className="rp-ring-center">
              <strong style={{ color: score !== null ? ringColor : "#9ca3af" }}>
                {score !== null ? score : "—"}
              </strong>
              <span>/100</span>
            </div>
          </div>
          <div className={`rp-verdict ${verdict.cls}`}>{verdict.label}</div>
          <p className="rp-summary">
            {report?.summary || "L'analyse de votre email est en cours…"}
          </p>
        </div>

        <div className="rp-divider" />

        {/* Détails */}
        <div>
          <div className="rp-section-title">Détails de l'email</div>
          <table className="rp-table">
            <tbody>
              <tr>
                <td>Fichier</td> <td>{emlData?.name || "—"}</td>
              </tr>
              <tr>
                <td>Expéditeur</td>
                <td style={{ wordBreak: "break-all" }}>{meta.from || "—"}</td>
              </tr>
              <tr>
                <td>Objet</td>
                <td style={{ wordBreak: "break-word", whiteSpace: "normal" }}>
                  {meta.subject || "—"}
                </td>
              </tr>
              <tr>
                <td>Liens</td>
                <td>{meta.links > 0 ? `${meta.links} lien(s)` : "Aucun"}</td>
              </tr>
              <tr>
                <td>Pièces jointes</td>
                <td>
                  {meta.attach > 0 ? `${meta.attach} pièce(s)` : "Aucune"}
                </td>
              </tr>
              <tr>
                <td>Date</td>
                <td>{meta.date || "—"}</td>
              </tr>
            </tbody>
          </table>
        </div>
      </div>

      {/* ── Panneau droit : chat ─────────────────────────────────────── */}
      <div className="rp-chat">
        <div className="rp-chat-topbar">
          <div className="rp-chat-topbar-icon">
            <BotIcon />
          </div>
          <div className="rp-chat-topbar-info">
            <h3>Assistant SecureMail</h3>
            <p>
              <span className="rp-dot" /> En ligne
            </p>
          </div>
          {(typing || busy) && (
            <span className="rp-thinking">Analyse en cours…</span>
          )}
        </div>

        <div className="rp-msgs" ref={msgsRef}>
          {msgs.map((m, i) => (
            <div key={i} className={`rp-msg ${m.role}`}>
              <div className="rp-msg-sender">
                {m.role === "bot" ? "Assistant" : "Vous"}
              </div>
              <div
                className="rp-bub"
                dangerouslySetInnerHTML={{ __html: parseMarkdown(m.text) }}
              />
              {m.chips?.length > 0 && (
                <div className="rp-chips">
                  {m.chips.map((c, j) => (
                    <button
                      key={j}
                      className="rp-chip"
                      onClick={() => setInput(c)}
                    >
                      {c}
                    </button>
                  ))}
                </div>
              )}
            </div>
          ))}
          {typing && (
            <div className="rp-msg bot">
              <div className="rp-msg-sender">Assistant</div>
              <div className="rp-tdots">
                <span />
                <span />
                <span />
              </div>
            </div>
          )}
        </div>

        <div className="rp-input-area">
          <div className="rp-input-box">
            <input
              className="rp-input"
              value={input}
              disabled={busy}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => e.key === "Enter" && sendMessage()}
              placeholder="Posez votre question sur cet email…"
            />
            <button
              className="rp-send"
              onClick={sendMessage}
              disabled={busy || !input.trim()}
            >
              <SendIcon />
            </button>
          </div>
          <p className="rp-input-hint">Appuyez sur Entrée pour envoyer</p>
        </div>
      </div>
    </div>
  );
}
